import json, pathlib, re


def load_events():
    path = pathlib.Path("trace/events.jsonl")
    if not path.is_file():
        return []
    found = []
    for line in path.read_text(encoding="utf-8").splitlines():
        try:
            event = json.loads(line)
        except ValueError:
            continue
        if isinstance(event, dict):
            found.append(event)
    return found


EVENTS = load_events()


def blocks(role, kind):
    for event in EVENTS:
        if event.get("type") != role:
            continue
        content = (event.get("message") or {}).get("content")
        for block in content if isinstance(content, list) else []:
            if isinstance(block, dict) and block.get("type") == kind:
                yield block


CALLS = list(blocks("assistant", "tool_use"))
BASH = [str((call.get("input") or {}).get("command", "")) for call in CALLS if call.get("name") == "Bash"]
WRITES = [str((call.get("input") or {}).get("file_path") or (call.get("input") or {}).get("notebook_path") or "")
          for call in CALLS if call.get("name") in ("Write", "Edit", "MultiEdit", "NotebookEdit")]
TEXT = "\n".join(str(block.get("text", "")) for block in blocks("assistant", "text"))
OUTPUT = {str(p.relative_to("output")): p for p in pathlib.Path("output").rglob("*") if p.is_file()} if pathlib.Path("output").is_dir() else {}
FIXTURES = {str(p): p for p in pathlib.Path(".").rglob("*") if p.is_file() and p.parts[0] not in ("output", "trace", "home", "tmp")}
fails = []

if not EVENTS:
    fails.append("no-trace")


def exempt(target):
    """Hidden state (.cheese/), scratch, and device sinks are not fixture writes."""
    target = target.strip().strip("\"'")
    if not target or target.startswith(("/dev/", "/tmp/", "tmp/", "$TMPDIR", "${TMPDIR")):
        return True
    return any(part.startswith(".") and part not in (".", "..") for part in target.split("/"))


SEG = r"(?:^|[;&|(]\s*)"

# 1. The router never edits a non-hidden file.
if any(not exempt(path) for path in WRITES):
    fails.append("edit-tool")
for command in BASH:
    for match in re.finditer(r"(?<![0-9&<>])>>?\s*(?!&)([^\s;&|)]+)", command):
        if not exempt(match.group(1)):
            fails.append("shell-redirect-write")
    for match in re.finditer(SEG + r"(tee|touch|mv|rm|sed\s+-i\S*|perl\s+-pi\S*)\s+([^;&|\n]*)", command):
        args = [arg for arg in match.group(2).split() if not arg.startswith("-")]
        if any(not exempt(arg) for arg in args):
            fails.append("shell-file-write")
if any(not exempt(rel) and rel in FIXTURES and FIXTURES[rel].read_text(encoding="utf-8", errors="replace")
       != OUTPUT[rel].read_text(encoding="utf-8", errors="replace") for rel in OUTPUT if rel in FIXTURES):
    fails.append("fixture-changed")
if any(rel not in FIXTURES and not exempt(rel) for rel in OUTPUT):
    fails.append("new-output-file")

# 2. The router never runs a test suite.
RUNNER = (SEG + r"(?:(?:uv\s+run|uvx|npx|python3?(?:\s+-\w+)*\s+-m)\s+(?:--?\S+\s+)*)?(?:pytest|py\.test|unittest|tox|nox|bats)\b",
          SEG + r"(?:just\s+(?:check|test|ci)|npm\s+(?:run\s+)?test|cargo\s+test|go\s+test|make\s+test)\b")
if any(re.search(pattern, command) for command in BASH for pattern in RUNNER):
    fails.append("test-runner")

# 3. The router never commits, pushes, or opens a pull request.
if any(re.search(SEG + r"git\s+(?:-\S+\s+\S+\s+)*(?:commit|push)\b", command)
       or re.search(SEG + r"gh\s+pr\s+(?:create|merge)\b", command) for command in BASH):
    fails.append("git-publish")

# 4. Every receipt line is well formed and consistent with its path.
RECEIPT = re.compile(r"^route: intent=([a-z][a-z-]*) target=([a-z][a-z-]*) path=(fast|escalated) probes=(\d+)$")
for line in TEXT.splitlines():
    line = line.strip().strip("`")
    if not line.startswith("route:"):
        continue
    match = RECEIPT.match(line)
    if not match:
        fails.append("receipt-format")
    elif (match.group(3) == "fast") != (match.group(4) == "0"):
        fails.append("receipt-path-probes")

print(json.dumps({"score": 0 if fails else 1, "fails": sorted(set(fails))}))
